+++ b/training/level-3/L3-017-extension-popup/manifest.json
@@ -0,0 +1,13 @@
+{
+  "manifest_version": 3,
+  "name": "L3-017 Popup",
+  "version": "1.0",
+  "description": "A bounded local capability popup application for training.",
+  "action": {
+    "default_popup": "popup.html",
+    "default_title": "L3-017 Popup"
+  },
+  "permissions": [
+    "storage"
+  ]
+}--- a/training/level-3/L3-017-extension-popup/popup.html
+++ b/training/level-3/L3-017-extension-popup/popup.html
@@ -0,0 +1,21 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>Extension Popup</title>
+  <link rel="stylesheet" href="popup.css">
+</head>
+<body>
+  <div class="container">
+    <h1>Extension Popup</h1>
+    <p id="status">Loading...</p>
+    <button id="toggleBtn">Toggle Feature</button>
+    <div id="checklist">
+      <h2>Checklist</h2>
+      <ul id="items"></ul>
+    </div>
+  </div>
+  <script src="popup.js"></script>
+</body>
+</html>--- a/training/level-3/L3-017-extension-popup/popup.css
+++ b/training/level-3/L3-017-extension-popup/popup.css
@@ -0,0 +1,50 @@
+/* CSS for extension popup */
+body {
+  width: 300px;
+  margin: 0;
+  padding: 10px;
+  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
+  background-color: #f5f5f5;
+}
+
+.container {
+  display: flex;
+  flex-direction: column;
+  gap: 10px;
+}
+
+h1 {
+  font-size: 18px;
+  margin: 0;
+  color: #333;
+}
+
+.checklist-item {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  padding: 8px;
+  background-color: white;
+  border-radius: 4px;
+  box-shadow: 0 1px 2px rgba(0,0,0,0.1);
+}
+
+.checklist-item input[type="checkbox"] {
+  margin: 0;
+  width: 16px;
+  height: 16px;
+}
+
+.checklist-item label {
+  flex: 1;
+  cursor: pointer;
+  user-select: none;
+}
+
+.status-bar {
+  display: flex;
+  justify-content: space-between;
+  font-size: 12px;
+  color: #666;
+  margin-top: 5px;
+}--- a/training/level-3/L3-017-extension-popup/popup.js
+++ b/training/level-3/L3-017-extension-popup/popup.js
@@ -0,0 +1,96 @@
+// popup.js - MV3 extension popup application
+// Local storage for persistent state
+const STORAGE_KEY = 'L3-017-extension-popup-state';
+
+// DOM elements
+const taskInput = document.getElementById('task-input');
+const addTaskBtn = document.getElementById('add-task');
+const taskList = document.getElementById('task-list');
+const clearAllBtn = document.getElementById('clear-all');
+
+// Load saved tasks
+function loadTasks() {
+    const saved = localStorage.getItem(STORAGE_KEY);
+    if (saved) {
+        return JSON.parse(saved);
+    }
+    return [];
+}
+
+// Save tasks to local storage
+function saveTasks(tasks) {
+    localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
+}
+
+// Render tasks to UI
+function renderTasks(tasks) {
+    taskList.innerHTML = '';
+    tasks.forEach((task, index) => {
+        const li = document.createElement('li');
+        li.className = 'task-item';
+        li.setAttribute('role', 'listitem');
+        
+        const checkbox = document.createElement('input');
+        checkbox.type = 'checkbox';
+        checkbox.checked = task.completed;
+        checkbox.setAttribute('aria-label', `Mark task "${task.text}" as ${task.completed ? 'incomplete' : 'complete'}`);
+        checkbox.addEventListener('change', () => {
+            tasks[index].completed = checkbox.checked;
+            saveTasks(tasks);
+            renderTasks(tasks);
+        });
+        
+        const span = document.createElement('span');
+        span.textContent = task.text;
+        span.className = task.completed ? 'completed' : '';
+        span.setAttribute('aria-label', `Task: ${task.text}`);
+        
+        const deleteBtn = document.createElement('button');
+        deleteBtn.textContent = 'Delete';
+        deleteBtn.className = 'delete-btn';
+        deleteBtn.setAttribute('aria-label', `Delete task "${task.text}"`);
+        deleteBtn.addEventListener('click', () => {
+            tasks.splice(index, 1);
+            saveTasks(tasks);
+            renderTasks(tasks);
+        });
+        
+        li.appendChild(checkbox);
+        li.appendChild(span);
+        li.appendChild(deleteBtn);
+        taskList.appendChild(li);
+    });
+}
+
+// Add new task
+function addTask() {
+    const text = taskInput.value.trim();
+    if (text) {
+        const tasks = loadTasks();
+        tasks.push({ text, completed: false });
+        saveTasks(tasks);
+        renderTasks(tasks);
+        taskInput.value = '';
+        taskInput.focus();
+    }
+}
+
+// Clear all tasks
+function clearAll() {
+    if (confirm('Are you sure you want to delete all tasks?')) {
+        saveTasks([]);
+        renderTasks([]);
+    }
+}
+
+// Initialize popup
+document.addEventListener('DOMContentLoaded', () => {
+    const tasks = loadTasks();
+    renderTasks(tasks);
+    
+    addTaskBtn.addEventListener('click', addTask);
+    taskInput.addEventListener('keypress', (e) => {
+        if (e.key === 'Enter') addTask();
+    });
+    clearAllBtn.addEventListener('click', clearAll);
+});

